def unboundedNodes(n, edges, src):
    INF = float('inf')
    dist = [INF] * n
    dist[src] = 0
    for _ in range(n - 1):
        changed = False
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                changed = True
        if not changed:
            return []
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append(v)
    bad = [False] * n
    stack = []
    for u, v, w in edges:
        if dist[u] != INF and dist[u] + w < dist[v] and not bad[v]:
            bad[v] = True
            stack.append(v)
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if not bad[v]:
                bad[v] = True
                stack.append(v)
    return [v for v in range(n) if bad[v]]
